    const s = Math.max(0.3, (meia - chanfro) / meia);
    const corpo = Manifold.extrude(cs, h - chanfro).translate([0, 0, z0 + chanfro]);
    const ponta = Manifold.extrude(cs.scale(s), 1e-3).translate([0, 0, z0]);
