    if (cfg.tipo === "quadrado") return n(cfg.lado) + " \xD7 " + n(cfg.lado) + " mm";
    if (cfg.tipo === "retangular") return n(cfg.comprimento) + " \xD7 " + n(cfg.largura) + " mm";
    if (cfg.tipo === "hexagonal") return "sextavado " + n(cfg.diametro) + " mm entre faces";
