            const B = novoObjeto({ nome: nomeB, transform: o.transform, partes: r.B.map((p) => ({ nome: p.nome, malha: p.malha, cor: p.cor, paleta: p.paleta })) });
            const extras = r.extras.map((x2, k) => novoObjeto({ nome: x2.nome, transform: o.transform, partes: [{ nome: x2.nome, malha: x2.malha, cor: x2.cor }] }));
